        private static void EnsureFolders(){Ensure("Assets/FOC/Generated");Ensure(Root);foreach(var name in new[]{"Meshes","Materials","Prefabs","Animations","Catalogs","Scenes","Specs"})Ensure(Root+"/"+name);foreach(var path in new[]{"Assets/FOC/Presentation/Characters","Assets/FOC/Presentation/Equipment","Assets/FOC/Presentation/Mounts","Assets/FOC/Presentation/Animations","Assets/FOC/Presentation/Materials","Assets/FOC/Presentation/VisualProfiles","Assets/FOC/ArtSource/Characters","Assets/FOC/ArtSource/Equipment","Assets/FOC/ArtSource/Mounts"})Ensure(path);}private static void Ensure(string path){if(AssetDatabase.IsValidFolder(path))return;var parent=path.Substring(0,path.LastIndexOf('/'));var name=path.Substring(path.LastIndexOf('/')+1);Ensure(parent);AssetDatabase.CreateFolder(parent,name);}
