        private static Mesh SkinnedBox(string name,float scale){var mesh=new Mesh{name=name};var x=0.24f*scale;var z=0.14f*scale;mesh.vertices=new[]{new Vector3(-x,0,-z),new Vector3(x,0,-z),new Vector3(x,0,z),new Vector3(-x,0,z),new Vector3(-x,1.25f*scale,-z),new Vector3(x,1.25f*scale,-z),new Vector3(x,1.25f*scale,z),new Vector3(-x,1.25f*scale,z)};mesh.triangles=new[]{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};mesh.normals=Enumerable.Repeat(Vector3.forward,8).ToArray();var weights=new BoneWeight[8];for(var i=0;i<8;i++)weights[i]=new BoneWeight{boneIndex0=i<4?0:1,weight0=1f};mesh.boneWeights=weights;mesh.bindposes=new[]{Matrix4x4.identity,Matrix4x4.Translate(new Vector3(0,-0.65f,0))};mesh.RecalculateBounds();var path=Root+"/Meshes/"+name+".asset";ReplaceAsset(mesh,path);return AssetDatabase.LoadAssetAtPath<Mesh>(path);}
        private static void CreateHumanPrefab(string name,Material material,MeshSet meshes,bool consolidated){var root=new GameObject(name);var rig=BuildHumanRig(root.transform);var renderers=new Renderer[3];var meshValues=new[]{meshes.skinned,meshes.skinnedLow,meshes.skinnedLow};var scales=new[]{Vector3.one,new Vector3(0.98f,0.98f,0.98f),new Vector3(0.90f,0.90f,0.90f)};for(var i=0;i<3;i++){var child=new GameObject("LOD"+i);child.transform.SetParent(root.transform,false);child.transform.localPosition=new Vector3(0,0.65f,0);child.transform.localScale=scales[i];var r=child.AddComponent<SkinnedMeshRenderer>();r.sharedMesh=meshValues[i];r.sharedMaterial=material;r.bones=new[]{rig.pelvis,rig.chest};r.rootBone=rig.pelvis;r.localBounds=new Bounds(new Vector3(0,0.65f,0),new Vector3(0.8f,1.5f,0.6f));renderers[i]=r;}var animator=root.AddComponent<Animator>();animator.cullingMode=AnimatorCullingMode.CullUpdateTransforms;var avatar=BuildAvatar(root,name);animator.avatar=avatar;var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(0.60f,new[]{renderers[0]}),new LOD(0.25f,new[]{renderers[1]}),new LOD(0.08f,new[]{renderers[2]})});lod.RecalculateBounds();if(consolidated)root.AddComponent<CharacterView3D>();SavePrefab(root,name);}
        private static Avatar BuildAvatar(GameObject root,string name){var map=new[]{("Pelvis","Hips"),("Spine","Spine"),("Chest","Chest"),("Neck","Neck"),("Head","Head"),("UpperArm_L","LeftUpperArm"),("LowerArm_L","LeftLowerArm"),("Hand_L","LeftHand"),("UpperArm_R","RightUpperArm"),("LowerArm_R","RightLowerArm"),("Hand_R","RightHand"),("UpperLeg_L","LeftUpperLeg"),("LowerLeg_L","LeftLowerLeg"),("Foot_L","LeftFoot"),("UpperLeg_R","RightUpperLeg"),("LowerLeg_R","RightLowerLeg"),("Foot_R","RightFoot")};var human=map.Select(x=>new HumanBone{boneName=x.Item1,humanName=x.Item2,limit=new HumanLimit{useDefaultValues=true}}).ToArray();var skeleton=root.GetComponentsInChildren<Transform>(true).Select(x=>new SkeletonBone{name=x.name,position=x.localPosition,rotation=x.localRotation,scale=x.localScale}).ToArray();var description=new HumanDescription{human=human,skeleton=skeleton,upperArmTwist=0.5f,lowerArmTwist=0.5f,upperLegTwist=0.5f,lowerLegTwist=0.5f,armStretch=0.05f,legStretch=0.05f,feetSpacing=0f,hasTranslationDoF=false};var avatar=AvatarBuilder.BuildHumanAvatar(root,description);avatar.name="AVATAR_"+name;var path=Root+"/Meshes/"+avatar.name+".asset";ReplaceAsset(avatar,path);return AssetDatabase.LoadAssetAtPath<Avatar>(path);}
