        private static HumanRig BuildHumanRig(Transform owner){var root=Bone(owner,"Root",Vector3.zero);var pelvis=Bone(root,"Pelvis",new Vector3(0,0.9f,0));var spine=Bone(pelvis,"Spine",new Vector3(0,0.25f,0));var chest=Bone(spine,"Chest",new Vector3(0,0.30f,0));var neck=Bone(chest,"Neck",new Vector3(0,0.28f,0));var head=Bone(neck,"Head",new Vector3(0,0.18f,0));var uaL=Bone(chest,"UpperArm_L",new Vector3(-0.28f,0.18f,0));var laL=Bone(uaL,"LowerArm_L",new Vector3(-0.30f,0,0));var handL=Bone(laL,"Hand_L",new Vector3(-0.24f,0,0));var uaR=Bone(chest,"UpperArm_R",new Vector3(0.28f,0.18f,0));var laR=Bone(uaR,"LowerArm_R",new Vector3(0.30f,0,0));var handR=Bone(laR,"Hand_R",new Vector3(0.24f,0,0));var ulL=Bone(pelvis,"UpperLeg_L",new Vector3(-0.13f,-0.12f,0));var llL=Bone(ulL,"LowerLeg_L",new Vector3(0,-0.44f,0));var footL=Bone(llL,"Foot_L",new Vector3(0,-0.42f,0.08f));var ulR=Bone(pelvis,"UpperLeg_R",new Vector3(0.13f,-0.12f,0));var llR=Bone(ulR,"LowerLeg_R",new Vector3(0,-0.44f,0));var footR=Bone(llR,"Foot_R",new Vector3(0,-0.42f,0.08f));Bone(handR,"Socket_RightHand",Vector3.zero);Bone(handL,"Socket_LeftHand",Vector3.zero);Bone(head,"Socket_Head",new Vector3(0,0.10f,0));Bone(chest,"Socket_BackPrimary",new Vector3(-0.12f,0,-0.15f));Bone(chest,"Socket_BackSecondary",new Vector3(0.12f,0,-0.15f));Bone(pelvis,"Socket_HipLeft",new Vector3(-0.20f,0,0));Bone(pelvis,"Socket_HipRight",new Vector3(0.20f,0,0));Bone(chest,"Socket_ShieldBack",new Vector3(0,0,-0.18f));return new HumanRig{pelvis=pelvis,chest=chest};}
        private static Transform Bone(Transform parent,string name,Vector3 local){var go=new GameObject(name);go.transform.SetParent(parent,false);go.transform.localPosition=local;return go.transform;}
