        private static void CreateMountPrefab(string name,Material material,MeshSet meshes){var root=new GameObject(name);var mountRoot=Bone(root.transform,"MountRoot",Vector3.zero);var pelvis=Bone(mountRoot,"MountPelvis",new Vector3(0,0.95f,0));var spine=Bone(pelvis,"MountSpine",new Vector3(0,0.15f,0.25f));var neck=Bone(spine,"MountNeck",new Vector3(0,0.15f,0.50f));Bone(neck,"MountHead",new Vector3(0,0.18f,0.28f));Bone(pelvis,"FrontLeg_L",new Vector3(-0.18f,-0.45f,0.35f));Bone(pelvis,"FrontLeg_R",new Vector3(0.18f,-0.45f,0.35f));Bone(pelvis,"BackLeg_L",new Vector3(-0.18f,-0.45f,-0.35f));Bone(pelvis,"BackLeg_R",new Vector3(0.18f,-0.45f,-0.35f));Bone(pelvis,CanonicalRig.RiderSocket,new Vector3(0,0.45f,0));var renderers=new Renderer[3];for(var i=0;i<3;i++){var child=new GameObject("LOD"+i);child.transform.SetParent(root.transform,false);child.transform.localPosition=new Vector3(0,0.95f,0);child.transform.localScale=new Vector3(0.70f-i*0.05f,0.65f-i*0.04f,1.25f-i*0.10f);var r=child.AddComponent<SkinnedMeshRenderer>();r.sharedMesh=i==0?meshes.skinned:meshes.skinnedLow;r.sharedMaterial=material;r.bones=new[]{pelvis,spine};r.rootBone=pelvis;renderers[i]=r;}var animator=root.AddComponent<Animator>();animator.cullingMode=AnimatorCullingMode.CullUpdateTransforms;var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(0.60f,new[]{renderers[0]}),new LOD(0.25f,new[]{renderers[1]}),new LOD(0.08f,new[]{renderers[2]})});lod.RecalculateBounds();SavePrefab(root,name);}
        private static RuntimeAnimatorController CreateAnimations(){var controllerPath=Root+"/Animations/ANM_SharedHuman.controller";var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(controllerPath);var createController=controller==null;if(createController)controller=AnimatorController.CreateAnimatorControllerAtPath(controllerPath);foreach(var name in ClipNames){var clip=new AnimationClip{name="ANM_"+name};clip.SetCurve("Root/Pelvis",typeof(Transform),"localPosition.y",AnimationCurve.EaseInOut(0,0.9f,1,name.Contains("Death")?0.2f:0.92f));var path=Root+"/Animations/ANM_"+name+".anim";ReplaceAsset(clip,path);if(createController)controller.AddMotion(AssetDatabase.LoadAssetAtPath<AnimationClip>(path));}return controller;}
