        private static void CreateCatalog(){var ids=new[]{"BODY_Human_Proof","CHR_Consolidated_Proof","HEAD_A_Proof","HEAD_B_Proof","CLTH_Light_Proof","CLTH_Specialist_Proof","ARM_Guard_Proof","ARM_Heavy_Proof","HDG_Wrapped_Proof","HDG_Cap_Proof","HDG_Guard_Proof","WPN_Sword_Proof","WPN_Lance_Proof","WPN_Polearm_Proof","WPN_Firearm_Proof","WPN_Pistol_Proof","AUX_Humbara_Proof","AUX_Ammo_Proof","SHD_Round_Proof","MNT_Horse_Proof","HAR_Harness_Proof","MARM_Proof"};var categories=new[]{VisualAssetCategory.Body,VisualAssetCategory.ConsolidatedCharacter,VisualAssetCategory.Head,VisualAssetCategory.Head,VisualAssetCategory.Clothing,VisualAssetCategory.Clothing,VisualAssetCategory.BodyArmor,VisualAssetCategory.BodyArmor,VisualAssetCategory.Headgear,VisualAssetCategory.Headgear,VisualAssetCategory.Headgear,VisualAssetCategory.Weapon,VisualAssetCategory.Weapon,VisualAssetCategory.Weapon,VisualAssetCategory.Weapon,VisualAssetCategory.Weapon,VisualAssetCategory.Auxiliary,VisualAssetCategory.Auxiliary,VisualAssetCategory.Shield,VisualAssetCategory.Mount,VisualAssetCategory.Harness,VisualAssetCategory.MountArmor};var assets=new List<VisualCatalogAsset.AssetEntry>();for(var i=0;i<ids.Length;i++)assets.Add(new VisualCatalogAsset.AssetEntry{id=ids[i],category=categories[i],prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/"+ids[i]+".prefab"),rigKind=categories[i]==VisualAssetCategory.Mount?RigKind.GenericMount:RigKind.Humanoid,lodCount=3,rendererCount=3,materialCount=1,sockets=categories[i]==VisualAssetCategory.Body||categories[i]==VisualAssetCategory.ConsolidatedCharacter?CanonicalRig.HumanSockets.Keys.ToArray():categories[i]==VisualAssetCategory.Mount?new[]{VisualSocket.Rider}:Array.Empty<VisualSocket>()});var profiles=new[]{new VisualCatalogAsset.ProfileEntry{visualProfileId="deli",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_A_Proof",clothingAssetId="CLTH_Light_Proof",headgearAssetId="HDG_Wrapped_Proof",cultureFamily="ottoman"},new VisualCatalogAsset.ProfileEntry{visualProfileId="humbaraci",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_B_Proof",clothingAssetId="CLTH_Specialist_Proof",headgearAssetId="HDG_Cap_Proof",cultureFamily="ottoman"},new VisualCatalogAsset.ProfileEntry{visualProfileId="bostanci",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_A_Proof",clothingAssetId="ARM_Guard_Proof",headgearAssetId="HDG_Guard_Proof",cultureFamily="ottoman"},new VisualCatalogAsset.ProfileEntry{visualProfileId="generic-european",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_B_Proof",clothingAssetId="ARM_Heavy_Proof",headgearAssetId="HDG_Guard_Proof",cultureFamily="european"}};var mappings=new[]{Map(EquipmentKind.Weapon,"lance","WPN_Lance_Proof",VisualSocket.RightHand),Map(EquipmentKind.Weapon,"sword","WPN_Sword_Proof",VisualSocket.HipLeft),Map(EquipmentKind.Weapon,"yatagan","WPN_Sword_Proof",VisualSocket.HipLeft),Map(EquipmentKind.Weapon,"musket","WPN_Firearm_Proof",VisualSocket.RightHand),Map(EquipmentKind.Weapon,"polearm","WPN_Polearm_Proof",VisualSocket.RightHand),Map(EquipmentKind.Weapon,"pistol","WPN_Pistol_Proof",VisualSocket.HipRight),Map(EquipmentKind.Weapon,"javelin","WPN_Lance_Proof",VisualSocket.BackPrimary),Map(EquipmentKind.Armor,"body-armor","ARM_Guard_Proof",VisualSocket.BackPrimary),Map(EquipmentKind.Armor,"mount-armor","MARM_Proof",VisualSocket.Rider),Map(EquipmentKind.Shield,"shield","SHD_Round_Proof",VisualSocket.LeftHand),Map(EquipmentKind.Mount,"fast-mount","MNT_Horse_Proof",VisualSocket.Rider),Map(EquipmentKind.Auxiliary,"shot","AUX_Ammo_Proof",VisualSocket.BackPrimary),Map(EquipmentKind.Auxiliary,"humbara","AUX_Humbara_Proof",VisualSocket.HipRight)};var catalog=ScriptableObject.CreateInstance<VisualCatalogAsset>();catalog.ReplaceContent(assets,profiles,mappings);ReplaceAsset(catalog,CatalogPath);}
