        private static void EnsureRuntimeVariants()
        {
            var catalog=AssetDatabase.LoadAssetAtPath<VisualCatalogAsset>(CatalogPath)??throw new InvalidOperationException("Visual catalog was not generated.");
            var assets=catalog.Assets.ToList();
            if(assets.All(x=>!StringComparer.Ordinal.Equals(x.id,"CRWD_Far_Proof")))assets.Add(new VisualCatalogAsset.AssetEntry{id="CRWD_Far_Proof",category=VisualAssetCategory.Crowd,prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/Prefabs/CRWD_Far_Proof.prefab"),rigKind=RigKind.Humanoid,lodCount=1,rendererCount=1,materialCount=1,sockets=Array.Empty<VisualSocket>()});
            var profiles=catalog.Profiles.ToList();
            profiles.Add(new VisualCatalogAsset.ProfileEntry{visualProfileId="proof-narrative",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_A_Proof",clothingAssetId="CLTH_Light_Proof",headgearAssetId="HDG_Wrapped_Proof",qualityTier=VisualQualityTier.Narrative,cultureFamily="proof"});
            profiles.Add(new VisualCatalogAsset.ProfileEntry{visualProfileId="proof-crowd",bodyAssetId="BODY_Human_Proof",headAssetId="HEAD_A_Proof",clothingAssetId="CLTH_Light_Proof",qualityTier=VisualQualityTier.Crowd,cultureFamily="proof"});
            catalog.ReplaceContent(assets,profiles,catalog.Equipment,"CHR_Consolidated_Proof","CRWD_Far_Proof",2);
            EditorUtility.SetDirty(catalog);
        }
